mapper.update:
UPDATE alarm
SET handle_state = #{handleState}
WHERE id = #{id}

mapper.select:
SELECT id, created_time `time`, category `type`, additional_info additionalInfo, severity level, `type` name, handle_state handleState
FROM alarm
WHERE `status` = 'ACTIVE_UNACK'

    AND handle_state = #{handleState}

ORDER BY created_time DESC, id

    limit #{page}, #{row}
